class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        from functools import lru_cache

        def cost(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        @lru_cache(maxsize=None)
        def dp(i, j, budget):
            if i > j:
                return 0
            if i == j:
                return 1
            best = max(dp(i + 1, j, budget), dp(i, j - 1, budget))
            c = cost(s[i], s[j])
            if c <= budget:
                best = max(best, 2 + dp(i + 1, j - 1, budget - c))
            return best

        result = dp(0, n - 1, k)
        dp.cache_clear()
        return result
